function addToCart(id){let sid=String(id);S.cart=S.cart||[];let row=S.cart.find(x=>String(x.id)===sid);if(row)row.qty=(row.qty||1)+1;else S.cart.push({id:sid,qty:1});save();alert('Added to cart.')}
function updateCartQty(id,d){let row=(S.cart||[]).find(x=>x.id===id);if(!row)return;row.qty=Math.max(1,(row.qty||1)+d);save();render()}
