function beginCheckout(){if(!(S.cart||[]).length)return alert('Your cart is empty.');if(!S.isAuthenticated){S.afterAuth='checkout';S.authMode='signin';save();return go('auth')}go('checkout')}
function checkoutPage(){if(!S.isAuthenticated){S.afterAuth='checkout';S.authMode='signin';save();return auth()}let d=Object.assign({name:S.profile.name||'',phone1:S.profile.phone||'',phone2:'',governorate:S.city||'',area:'',address:''},S.checkout||{});return page('Delivery Information',`<h1 class="title">Delivery details</h1><p class="sub">These details will be sent to the merchant with your order.</p><div class="card"><label>Customer name</label><input id="coName" class="field" value="${d.name||''}" placeholder="Full name"><label>Primary phone</label><input id="coPhone1" class="field" inputmode="tel" value="${d.phone1||''}" placeholder="Primary phone number"><label>Backup phone</label><input id="coPhone2" class="field" inputmode="tel" value="${d.phone2||''}" placeholder="Backup phone number"><label>Governorate / State</label><input id="coGov" class="field" value="${d.governorate||''}" placeholder="Governorate / State"><label>Area</label><input id="coArea" class="field" value="${d.area||''}" placeholder="Area / District"><label>Full address</label><textarea id="coAddress" class="field textarea" placeholder="Street, building, nearest landmark">${d.address||''}</textarea><button class="primary" onclick="placeOrder()">Confirm Order</button></div>`,'cart')}
async function placeOrder(){if(!S.isAuthenticated)return beginCheckout();let d={name:document.getElementById('coName').value.trim(),phone1:document.getElementById('coPhone1').value.trim(),phone2:document.getElementById('coPhone2').value.trim(),governorate:document.getElementById('coGov').value.trim(),area:document.getElementById('coArea').value.trim(),address:document.getElementById('coAddress').value.trim()};if(!d.name||!d.phone1||!d.governorate||!d.area||!d.address)return alert('Complete the required delivery information.');let grouped={};(S.cart||[]).forEach(x=>{let p=findOffer(x.id);if(!p)return;let key=p.remoteMerchantId||('local:'+String(p.shop||'Merchant')),g=grouped[key]||(grouped[key]={merchantName:p.shop||'Merchant',merchantId:p.remoteMerchantId||null,items:[]}),attrs=(S.offerAttributes||{})[String(p.id)]||{};g.items.push({id:String(x.id),qty:x.qty||1,title:p.title,unit_price:priceNumber(p),attributes:attrs,snapshot:{shop:p.shop,city:p.city,price:p.price,old:p.old,off:p.off}})});let now=Date.now(),cur=D.markets[S.market]?.currency||'IQD',orders=Object.values(grouped).map((g,i)=>({id:'MIRA-'+String(now+i).slice(-8),createdAt:new Date().toISOString(),status:0,merchantName:g.merchantName,merchantId:g.merchantId,delivery:d,currency:cur,items:g.items,subtotal:g.items.reduce((n,x)=>n+x.unit_price*x.qty,0)}));if(!orders.length)return alert('Your cart is empty.');if(window.MIRA_DB?.enabled){try{for(const o of orders){let rr=await MIRA_DB.insertOrder({merchant_id:o.merchantId,market:S.market,currency:o.currency,delivery:o.delivery,subtotal:o.subtotal,items:o.items});o.remoteOrderId=rr.id;o.id=rr.order_number||o.id}}catch(e){return alert(e.message||'Could not place the order.')}}S.checkout=d;S.orders=S.orders||[];S.orders.unshift(...orders);S.cart=[];S.selectedOrder=orders[0].id;save();go('orderTracking')}
function myOrders(){let rows=S.orders||[];if(!rows.length)return page('My Orders','<div class="empty">You have no orders yet.</div><button class="primary" onclick="go(\'home\')">Start Shopping</button>','profile');return page('My Orders',rows.map(o=>`<div class="item" onclick="openOrder('${o.id}')"><div class="ico">📦</div><div class="grow"><b>${o.id}</b><div class="small">${o.merchantName||'Merchant'} • ${ORDER_STATUSES[o.status]||ORDER_STATUSES[0]} • ${new Date(o.createdAt).toLocaleDateString()}</div></div>›</div>`).join(''),'profile')}
function openOrder(id){S.selectedOrder=id;save();go('orderTracking')}
function orderTracking(){let o=(S.orders||[]).find(x=>x.id===S.selectedOrder);if(!o)return page('Order Tracking','<div class="empty">Order not found.</div>','myOrders');let products=o.items.map(x=>{let p=findOffer(x.id);return p?`${p.title} × ${x.qty}`:''}).filter(Boolean).join(' • ');return page('Order Tracking',`<div class="card"><b>${o.id}</b><div class="small">${o.merchantName||'Merchant'}</div><div class="small">${products}</div><div class="notice">Current status: <b>${ORDER_STATUSES[o.status]}</b></div></div><div class="section"><h3>Tracking</h3></div>${ORDER_STATUSES.map((s,i)=>`<div class="item"><div class="ico">${i<o.status?'✓':i===o.status?'●':'○'}</div><div class="grow"><b>${s}</b><div class="small">${i===o.status?'Current status':i<o.status?'Completed':'Pending'}</div></div></div>`).join('')}<div class="section"><h3>Delivery</h3></div><div class="card"><b>${o.delivery.name}</b><div class="small">${o.delivery.phone1}${o.delivery.phone2?' • '+o.delivery.phone2:''}</div><div class="small">${o.delivery.governorate} • ${o.delivery.area}</div><p>${o.delivery.address}</p></div>`,'myOrders')}
function merchantOrders(){let rows=(S.orders||[]).filter(o=>!o.merchantName||o.merchantName===S.merchant.name);let refresh='<button class="secondary" onclick="syncRemoteMerchantOrders()">Refresh Orders</button>';if(!rows.length)return page('Orders',refresh+'<div class="empty">No customer orders for this merchant yet.</div>','merchant');return page('Orders',refresh+rows.map(o=>{let items=o.items.map(x=>{let p=findOffer(x.id);return p?`${p.title} × ${x.qty}`:''}).filter(Boolean).join(' • ');return `<div class="card" style="margin-bottom:12px"><div class="section"><h3>${o.id}</h3><span class="small">${ORDER_STATUSES[o.status]}</span></div><div><b>${o.delivery.name}</b></div><div class="small">Primary: ${o.delivery.phone1}</div><div class="small">Backup: ${o.delivery.phone2||'—'}</div><div class="small">${o.delivery.governorate} • ${o.delivery.area}</div><p>${o.delivery.address}</p><div class="small">${items}</div><button class="primary" onclick="advanceOrder('${o.id}')">${o.status<ORDER_STATUSES.length-1?'Move to '+ORDER_STATUSES[o.status+1]:'Delivered'}</button></div>`}).join(''),'merchant')}
async function advanceOrder(id){let o=(S.orders||[]).find(x=>String(x.id)===String(id));if(!o)return;if(o.status>=ORDER_STATUSES.length-1)return;let next=o.status+1;if(window.MIRA_DB?.enabled&&o.remoteOrderId){try{await MIRA_DB.updateOrderStatus(o.remoteOrderId,ORDER_STATUS_KEYS[next])}catch(e){return alert(e.message||'Could not update order status.')}}o.status=next;save();render()}
function remoteOrderToLocal(r,merchantName){let items=(r.order_items||[]).map(x=>({id:String(x.product_ref||x.product_id||x.id),qty:x.quantity||1,title:x.product_title,unit_price:Number(x.unit_price||0),attributes:x.attributes||{},snapshot:x.snapshot||{}})),idx=ORDER_STATUS_KEYS.indexOf(r.status);return {id:r.order_number||String(r.id),remoteOrderId:r.id,createdAt:r.created_at,status:idx<0?0:idx,merchantName:merchantName||'Merchant',merchantId:r.merchant_id||null,delivery:{name:r.customer_name,phone1:r.phone_primary,phone2:r.phone_secondary||'',governorate:r.governorate,area:r.area,address:r.address},currency:r.currency||'IQD',items,subtotal:Number(r.subtotal||0)}}
async function syncRemoteCustomerOrders(){if(!window.MIRA_DB?.enabled||!S.isAuthenticated)return;try{let rows=await MIRA_DB.listCustomerOrders(),known=new Set((S.orders||[]).filter(x=>x.remoteOrderId).map(x=>String(x.remoteOrderId))),added=[];for(const r of rows)if(!known.has(String(r.id)))added.push(remoteOrderToLocal(r));if(added.length){S.orders=S.orders||[];S.orders.unshift(...added);save();render()}}catch(e){console.warn('MIRA customer orders sync failed',e)}}
async function syncRemoteMerchantOrders(){if(!window.MIRA_DB?.enabled||!S.isAuthenticated)return;try{let rows=await MIRA_DB.listMerchantOrders(),byRemote=new Map((S.orders||[]).filter(x=>x.remoteOrderId).map(x=>[String(x.remoteOrderId),x])),changed=false;for(const r of rows){let idx=ORDER_STATUS_KEYS.indexOf(r.status),existing=byRemote.get(String(r.id));if(existing){if(idx>=0&&existing.status!==idx){existing.status=idx;changed=true}}else{S.orders=S.orders||[];S.orders.unshift(remoteOrderToLocal(r,S.merchant.name));changed=true}}if(changed){save();render()}}catch(e){console.warn('MIRA merchant orders sync failed',e)}}
async function shareOffer(id){let o=findOffer(id);try{if(navigator.share)await navigator.share({title:o.title,text:`${o.title} - ${o.off} OFF`});else alert(`${o.title} - ${o.off} OFF`)}catch(e){}}function explore(){return `<section class="screen">${top('Explore')}<div class="content"><div class="map"><span class="pin" style="left:22%;top:28%">📍</span><span class="pin" style="left:60%;top:48%">📍</span><span class="pin" style="left:43%;top:67%">📍</span></div><div class="section"><h3>Offers Near Me</h3><button class="link" onclick="go('filters')">Filters</button></div>${allOffers().slice(0,4).map(o=>`<div class="item" onclick="openOffer('${jsId(o.id)}')"><div class="ico">${o.emoji}</div><div class="grow"><b>${o.title}</b><div class="small">${o.shop} • ${o.city}</div></div><b style="color:var(--p)">${o.off}</b></div>`).join('')}</div>${nav('explore')}</section>`}function filters(){return page('Filters',`<div class="card"><label>Distance</label><select class="field"><option>Nearby</option><option>1 km</option><option>5 km</option><option>10 km</option><option>25 km</option></select><label>Minimum discount</label><select class="field"><option>Any</option><option>20%+</option><option>30%+</option><option>50%+</option></select><label>Sort</label><select class="field"><option>Recommended</option><option>Nearest</option><option>Biggest Discount</option><option>Newest</option><option>Ending Soon</option></select><button class="primary" onclick="go('explore')">Apply Filters</button></div>`,'explore')}function search(){return `<section class="screen">${top('Search')}<div class="content"><div class="search">⌕ <input id="q" placeholder="Search offers, stores, brands..." oninput="runSearch(this.value)"></div><div class="section"><h3>Trending</h3></div><div class="chips">${['Samsung','Shoes','Coffee','TV','Beauty','Home'].map(x=>`<button class="chip" onclick="document.getElementById('q').value='${x}';runSearch('${x}')">${x}</button>`).join('')}</div><div id="searchResults"><div class="section"><h3>Popular Offers</h3></div><div class="offers">${allOffers().slice(0,4).map(offerCard).join('')}</div></div></div>${nav('search')}</section>`}function runSearch(q){let r=allOffers().filter(o=>(o.title+' '+o.shop+' '+o.cat).toLowerCase().includes(q.toLowerCase()));document.getElementById('searchResults').innerHTML=`<div class="section"><h3>Results</h3><span class="small">${r.length}</span></div><div class="offers">${r.map(offerCard).join('')||'<div class="empty">No results found.</div>'}</div>`}function favorites(){let r=allOffers().filter(o=>S.favorites.includes(o.id));return `<section class="screen">${top('Favorites')}<div class="content"><div class="tabs"><button class="on">Saved Offers</button><button onclick="go('followed')">Saved Stores</button></div>${r.length?`<div class="offers">${r.map(offerCard).join('')}</div>`:'<div class="empty">No saved offers yet.</div>'}</div>${nav('favorites')}</section>`}function followed(){return page('Followed Stores',`<div class="item" onclick="go('store')"><div class="ico">S</div><div class="grow"><b>Samsung House</b><div class="small">3 active offers</div></div>›</div>`,'favorites','favorites')}function store(){let f=S.following.includes(1);return page('Store Profile',`<div class="profile"><div class="avatar">S</div><h2>Samsung House ✓</h2><div class="small">Electronics • Baghdad • Open now</div></div><button class="store-heart ${f?'on':''}" onclick="toggleFollow()">${f?'♥ Saved Store':'♡ Save Store'}</button><div class="section"><h3>Current Offers</h3></div><div class="offers">${allOffers().filter(o=>o.cat==='Electronics').map(offerCard).join('')}</div><div class="section"><h3>Branches</h3></div><div class="item"><div class="ico">📍</div><div class="grow"><b>Mansour Branch</b><div class="small">10:00 AM – 10:00 PM • 2.4 km</div></div></div>`,'detail')}function toggleFollow(){S.following=S.following.includes(1)?S.following.filter(x=>x!==1):[...S.following,1];save();render()}function notifications(){return page('Notifications',`<div class="item"><div class="ico">⚡</div><div><b>Flash Sale started</b><div class="small">Samsung has a new offer near you.</div></div></div><div class="item"><div class="ico">♥</div><div><b>Favorite store update</b><div class="small">Urban Men published a new offer.</div></div></div><div class="item"><div class="ico">⏳</div><div><b>Ending soon</b><div class="small">Your saved offer ends tonight.</div></div></div>`,'home')}function profile(){return `<section class="screen">${top('Profile')}<div class="content"><div class="profile"><div class="avatar">${(S.profile.name||'M')[0]}</div><h2>${S.profile.name||'MIRA User'}</h2><div class="small">${S.city}, ${S.market}</div></div>${[['🛒','Cart','cart'],['📦','My Orders','myOrders'],['🌍','Shopping Market','market'],['✨','Shopping Interests','interests'],['🔔','Notification Settings','notificationSettings'],['🕘','Recently Viewed','recent'],['❓','Help & Support','support'],['🏪','Merchant Portal','merchant'],['🛡️','Admin Dashboard','admin'],['⚙️','Settings','settings']].map(x=>`<div class="item" onclick="go('${x[2]}')"><div class="ico">${x[0]}</div><div class="grow"><b>${x[1]}</b></div>›</div>`).join('')}</div>${nav('profile')}</section>`}function notificationSettings(){return page('Notification Settings',`<div class="card">${[['near','Nearby offers'],['flash','Flash Sales'],['stores','Favorite stores'],['special','MIRA Specials']].map(x=>`<div class="switch"><b>${x[1]}</b><button class="toggle ${S.notifications[x[0]]?'on':''}" onclick="S.notifications.${x[0]}=!S.notifications.${x[0]};save();render()"></button></div>`).join('')}</div>`,'profile')}function recent(){let r=S.recent.map(id=>allOffers().find(o=>o.id===id)).filter(Boolean);return page('Recently Viewed',r.length?`<div class="offers">${r.map(offerCard).join('')}</div>`:'<div class="empty">Nothing viewed yet.</div>','profile')}function support(){return page('Help & Support',`<div class="card"><select id="supportCat" class="field"><option>Account</option><option>Offers</option><option>Merchants</option><option>Technical issue</option></select><input id="supportSub" class="field" placeholder="Subject"><textarea id="supportBody" class="field textarea" placeholder="Describe your issue"></textarea><button class="primary" onclick="submitSupport()">Submit Ticket</button></div>`,'profile')}function submitSupport(){if(!document.getElementById('supportSub').value.trim())return alert('Enter a subject.');alert('Support ticket submitted.');go('profile')}function report(){return page('Report Offer',`<div class="card"><select class="field"><option>Incorrect price</option><option>Expired offer</option><option>Misleading offer</option><option>Wrong location</option><option>Scam / fraud suspicion</option><option>Other</option></select><textarea class="field textarea" placeholder="Details"></textarea><button class="primary" onclick="alert('Report submitted.');go('home')">Submit Report</button></div>`,'detail')}function merchant(){return page('Merchant Portal',`<div class="banner"><small>Business Dashboard</small><h2>${S.merchant.name}</h2><div>${S.merchant.verified?'Verified':'Pending'} • ${S.city}</div></div><div class="section"><h3>Overview</h3></div><div class="kpis"><div class="kpi"><span class="small">Active Offers</span><strong>${S.merchant.offers}</strong></div><div class="kpi"><span class="small">Views</span><strong>18.4K</strong></div><div class="kpi"><span class="small">Favorites</span><strong>220</strong></div><div class="kpi"><span class="small">Leads</span><strong>143</strong></div></div><div class="section"><h3>Tools</h3></div>${[['📦','Orders','merchantOrders'],['🏷️','Manage Offers','manageOffers'],['＋','Create Offer','createOffer'],['📊','Analytics','analytics'],['📍','Branches','branches'],['💳','Subscription & Billing','billing']].map(x=>`<div class="item" onclick="go('${x[2]}')"><div class="ico">${x[0]}</div><div class="grow"><b>${x[1]}</b></div>›</div>`).join('')}`,'profile')}function createOffer(){return page('Create Offer',`<div class="card"><input id="ot" class="field" placeholder="Offer title"><input class="field" placeholder="Original price"><input class="field" placeholder="Offer price"><select class="field"><option>Standard Offer</option><option>Flash Sale</option><option>Featured Offer</option></select><select class="field"><option>All branches</option><option>Mansour</option><option>Karrada</option></select><input class="field" type="datetime-local"><input class="field" type="datetime-local"><button class="secondary" onclick="alert('Preview ready.')">Preview Offer</button><button class="primary" onclick="publishOffer()">Publish Offer</button></div>`,'merchant')}function publishOffer(){if(!document.getElementById('ot').value.trim())return alert('Enter an offer title.');S.merchant.offers++;save();alert('Offer published.');go('merchant')}function manageOffers(){return page('Manage Offers',allOffers().slice(0,3).map(o=>`<div class="item"><div class="ico">${o.emoji}</div><div class="grow"><b>${o.title}</b><div class="small">Active • ${o.off} OFF</div></div><button class="link">Edit</button></div>`).join(''),'merchant')}function analytics(){return page('Merchant Analytics',`<div class="kpis"><div class="kpi"><span class="small">Impressions</span><strong>18K</strong></div><div class="kpi"><span class="small">Offer Views</span><strong>2.1K</strong></div><div class="kpi"><span class="small">WhatsApp</span><strong>95</strong></div><div class="kpi"><span class="small">Directions</span><strong>48</strong></div></div>`,'merchant')}function branches(){return page('Branches',`<div class="item"><div class="ico">📍</div><div class="grow"><b>Mansour</b><div class="small">10 AM – 10 PM</div></div>Edit</div><div class="item"><div class="ico">📍</div><div class="grow"><b>Karrada</b><div class="small">10 AM – 11 PM</div></div>Edit</div><button class="primary" onclick="alert('Branch editor opened.')">Add Branch</button>`,'merchant')}function billing(){return page('Subscription & Billing',`<div class="card"><h2>Business Plan</h2><p class="sub">5 branches • analytics • promoted offer access</p><button class="primary" onclick="alert('Billing provider will open here.')">Manage Plan</button></div>`,'merchant')}function admin(){return page('Admin Dashboard',`<div class="banner"><small>MIRA Control Center</small><h2>Admin Dashboard</h2><div>${S.market} Market • Live</div></div><div class="section"><h3>Platform KPIs</h3></div><div class="kpis"><div class="kpi"><span class="small">Users</span><strong>12.8K</strong></div><div class="kpi"><span class="small">Merchants</span><strong>428</strong></div><div class="kpi"><span class="small">Active Offers</span><strong>1,245</strong></div><div class="kpi"><span class="small">Pending</span><strong>17</strong></div></div><div class="section"><h3>Admin Tools</h3></div>${[['🏪','Merchant Approvals','approvals'],['✅','Offer Moderation','moderation'],['🎯','Campaigns','campaigns'],['🌍','Markets','markets'],['💰','Revenue','revenue'],['🚩','Reports','reports']].map(x=>`<div class="item" onclick="go('${x[2]}')"><div class="ico">${x[0]}</div><div class="grow"><b>${x[1]}</b></div>›</div>`).join('')}`,'profile')}function simpleAdmin(title,items){return page(title,items.map(x=>`<div class="item"><div class="ico">✓</div><div class="grow"><b>${x}</b><div class="small">Awaiting review</div></div><button class="link" onclick="alert('Approved')">Approve</button></div>`).join(''),'admin')}function campaigns(){return page('Campaigns',`<div class="card"><input class="field" value="Weekend Deals Baghdad"><select class="field"><option>MIRA Specials</option><option>Home Hero</option><option>Featured Stores</option><option>Sponsored Search</option></select><button class="primary" onclick="alert('Campaign published.')">Publish Campaign</button></div>`,'admin')}function markets(){return page('Markets',`<div class="item"><div class="ico">🇮🇶</div><div class="grow"><b>Iraq</b><div class="small">IQD • Active</div></div></div><div class="item"><div class="ico">🇦🇪</div><div class="grow"><b>UAE</b><div class="small">AED • Ready</div></div></div><div class="item"><div class="ico">🇸🇦</div><div class="grow"><b>Saudi Arabia</b><div class="small">SAR • Ready</div></div></div>`,'admin')}function revenue(){return page('Revenue',`<div class="kpis"><div class="kpi"><span class="small">Subscriptions</span><strong>$18.2K</strong></div><div class="kpi"><span class="small">Sponsored</span><strong>$7.4K</strong></div><div class="kpi"><span class="small">Featured</span><strong>$3.1K</strong></div><div class="kpi"><span class="small">MRR</span><strong>$25.6K</strong></div></div>`,'admin')}function settings(){return page('Settings',`<div class="item" onclick="go('privacy')"><div class="ico">🔒</div><div class="grow"><b>Privacy Policy</b></div>›</div><div class="item" onclick="go('terms')"><div class="ico">📄</div><div class="grow"><b>Terms of Use</b></div>›</div><div class="item" onclick="resetApp()"><div class="ico">↪</div><div class="grow"><b>Sign Out</b></div></div><button class="secondary danger" onclick="deleteAccount()">Delete Account</button>`,'profile')}async function resetApp(){try{if(window.MIRA_DB?.enabled)await MIRA_DB.signOut()}catch(e){console.warn('MIRA sign out failed',e)}localStorage.removeItem('miraState');S=JSON.parse(JSON.stringify(defaults));go('welcome')}function deleteAccount(){if(confirm('Delete this MIRA account and local profile data?')){localStorage.clear();S=JSON.parse(JSON.stringify(defaults));alert('Account deletion request created and local data cleared.');go('welcome')}}function legal(kind){let privacy=kind==='privacy';return page(privacy?'Privacy Policy':'Terms of Use',`<div class="card"><h2>${privacy?'Privacy Policy':'Terms of Use'}</h2><p>${privacy?'MIRA processes account details, selected shopping preferences, saved items and location only when permission is granted. Location can be disabled at any time. MIRA does not sell personal data.':'MIRA is an offers discovery platform. Merchants remain responsible for pricing, stock, product claims and branch availability. Users must use the platform lawfully and avoid abuse or fraud.'}</p><p class="small">Last updated: October 2026.</p></div>`,'settings')}function render(){document.documentElement.dir=S.lang==='ar'?'rtl':'ltr';let r=S.route||'welcome',html='';if(r==='welcome')html=welcome();else if(r==='auth')html=auth();else if(r==='otp')html=otp();else if(r==='emailSent')html=emailSent();else if(r==='market')html=market();else if(r==='city')html=city();else if(r==='interests')html=interests();else if(r==='home')html=home();else if(r==='offers')html=offers();else if(r==='category')html=category();else if(r==='detail')html=detail();else if(r==='cart')html=cartPage();else if(r==='checkout')html=checkoutPage();else if(r==='myOrders')html=myOrders();else if(r==='orderTracking')html=orderTracking();else if(r==='explore')html=explore();else if(r==='filters')html=filters();else if(r==='search')html=search();else if(r==='favorites')html=favorites();else if(r==='followed')html=followed();else if(r==='store')html=store();else if(r==='notifications')html=notifications();else if(r==='profile')html=profile();else if(r==='notificationSettings')html=notificationSettings();else if(r==='recent')html=recent();else if(r==='support')html=support();else if(r==='report')html=report();else if(r==='merchant')html=merchant();else if(r==='merchantOrders')html=merchantOrders();else if(r==='createOffer')html=createOffer();else if(r==='manageOffers')html=manageOffers();else if(r==='analytics')html=analytics();else if(r==='branches')html=branches();else if(r==='billing')html=billing();else if(r==='admin')html=admin();else if(r==='taxonomyAdmin')html=taxonomyAdmin();else if(r==='productClassification')html=productClassificationAdmin();else if(r==='productClassificationEdit')html=productClassificationEditor();else if(r==='approvals')html=simpleAdmin('Merchant Approvals',['Future Tech','Baghdad Style','Urban Coffee']);else if(r==='moderation')html=simpleAdmin('Offer Moderation',['50% Fashion Sale','Weekend Electronics','Coffee Bundle']);else if(r==='campaigns')html=campaigns();else if(r==='markets')html=markets();else if(r==='revenue')html=revenue();else if(r==='reports')html=simpleAdmin('Reports & Moderation',['Incorrect price • Offer #1024','Misleading offer • Offer #1081']);else if(r==='settings')html=settings();else if(r==='privacy')html=legal('privacy');else if(r==='terms')html=legal('terms');else html=home();root.innerHTML=`<div class="app">${html}</div>`}window.syncRemoteMerchantOrders=syncRemoteMerchantOrders;window.addToCart=addToCart;window.updateCartQty=updateCartQty;window.removeFromCart=removeFromCart;window.beginCheckout=beginCheckout;window.placeOrder=placeOrder;window.openOrder=openOrder;window.advanceOrder=advanceOrder;window.go=go;window.setLang=setLang;window.submitAuth=submitAuth;window.verifyOtp=verifyOtp;window.refreshAuthSession=refreshAuthSession;window.submitAuthAgain=submitAuthAgain;window.resendPhoneOtp=resendPhoneOtp;window.toggleInterest=toggleInterest;window.openCategory=openCategory;window.openOffer=openOffer;window.toggleFav=toggleFav;window.shareOffer=shareOffer;window.runSearch=runSearch;window.toggleFollow=toggleFollow;window.submitSupport=submitSupport;window.publishOffer=publishOffer;window.resetApp=resetApp;window.deleteAccount=deleteAccount;/* Dynamic MIRA taxonomy integration */
function txName(x){return S.lang==='ar'?(x.ar||x.en):(x.en||x.ar)}
function txSource(){return S.taxonomyData||(window.MIRA_TAXONOMY||[])}
function persistTaxonomy(){S.taxonomyData=JSON.parse(JSON.stringify(txSource()));save()}
function txCat(slug){return txSource().find(x=>x.slug===slug)}
function txSub(cat,slug){return cat&&cat.subs.find(x=>x.slug===slug)}
function txTypeName(t){return S.lang==='ar'?t[1]:t[2]}
function txSubKey(cat,sub){return cat.slug+'/'+sub.slug}
function txTypeKey(cat,sub,t){return cat.slug+'/'+sub.slug+'/'+t[0]}
function txVisibleSubs(cat){let o=(S.taxonomyOverrides?.subOrder||{})[cat.slug]||[],h=S.taxonomyOverrides?.hiddenSubs||[],a=[...(cat.subs||[])];a.sort((x,y)=>{let ix=o.indexOf(x.slug),iy=o.indexOf(y.slug);return (ix<0?999:ix)-(iy<0?999:iy)});return a.filter(s=>!h.includes(txSubKey(cat,s)))}
function txVisibleTypes(cat,sub){let key=cat.slug+'/'+sub.slug,o=(S.taxonomyOverrides?.typeOrder||{})[key]||[],h=S.taxonomyOverrides?.hiddenTypes||[],a=[...(sub.types||[])];a.sort((x,y)=>{let ix=o.indexOf(x[0]),iy=o.indexOf(y[0]);return (ix<0?999:ix)-(iy<0?999:iy)});return a.filter(t=>!h.includes(txTypeKey(cat,sub,t)))}
function txAll(){let a=[...txSource()],o=(S.taxonomyOverrides&&S.taxonomyOverrides.order)||[],h=(S.taxonomyOverrides&&S.taxonomyOverrides.hidden)||[];a.sort((x,y)=>{let ix=o.indexOf(x.slug),iy=o.indexOf(y.slug);return (ix<0?999:ix)-(iy<0?999:iy)});return a.filter(x=>!h.includes(x.slug))}
function taxonomyHomeCats(){return txAll().map(c=>`<button class="cat" onclick="openCategory('${c.slug}')"><b>⌄</b>${txName(c)}</button>`).join('')}
home=function(){return `<section class="screen">${top('')}<div class="content"><div class="search" onclick="go('search')">⌕ <span class="small">Search offers, stores, brands...</span></div><button class="secondary" onclick="go('cart')">🛒 Cart (${cartCount()})</button><div style="height:13px"></div><div class="banner"><small>${S.city}, ${S.market}</small><h2>Deals made for you</h2><div>Fresh offers from stores you love.</div></div><div class="section"><h3>Flash Sales</h3><button class="link" onclick="go('offers')">See All</button></div><div class="offers">${allOffers().slice(0,2).map(offerCard).join('')}</div><div class="section"><h3>Shop by Category</h3></div><div class="cats">${taxonomyHomeCats()}</div><div class="section"><h3>Recommended for You</h3><button class="link" onclick="go('offers')">See All</button></div><div class="offers">${allOffers().slice(2).map(offerCard).join('')}</div></div>${nav('home')}</section>`}
interests=function(){let cats=txAll();return page('Interests',`<h1 class="title">What are you interested in?</h1><p class="sub">Choose as many as you like.</p><div class="chips">${cats.map(c=>`<button class="chip ${S.interests.includes(c.slug)?'on':''}" onclick="toggleInterest('${c.slug}')">${txName(c)}</button>`).join('')}</div><button class="primary" onclick="go('home')">Start exploring</button><button class="secondary" onclick="go('home')">Skip for now</button>`,'city')}
openCategory=function(slug){S.category=slug;S.subcategory='';S.productType='';save();go('category')}
function chooseSub(slug){S.subcategory=slug;S.productType='';S.productFilters={};save();render()}
function chooseType(slug){S.productType=slug;S.productFilters={};save();render()}
function setProductFilter(key,value){S.productFilters=S.productFilters||{};if(value)S.productFilters[key]=value;else delete S.productFilters[key];save();render()}
function clearProductFilters(){S.productFilters={};save();render()}
function categoryFilterFields(type){let attrs=(type&&type[3])||[],filters=S.productFilters||{},usable=attrs.filter(a=>a.is_filterable!==false);if(!usable.length)return '';return `<div class="section"><h3>Filters</h3><button class="link" onclick="clearProductFilters()">Clear</button></div><div class="card">${usable.map(a=>{let label=a.label||a.key,opts=a.options||[];if((a.input_type==='select'||a.input_type==='multiselect')&&opts.length)return `<label>${label}</label><select class="field" onchange="setProductFilter('${a.key}',this.value)"><option value="">Any</option>${opts.map(o=>`<option ${String(filters[a.key]||'')===String(o)?'selected':''}>${o}</option>`).join('')}</select>`;return `<label>${label}</label><input class="field" value="${filters[a.key]||''}" placeholder="Any" onchange="setProductFilter('${a.key}',this.value.trim())">`}).join('')}</div>`}
category=function(){let cat=txCat(S.category);if(!cat)return offers(allOffers(),'Category');let sub=txSub(cat,S.subcategory);let type=sub&&sub.types.find(t=>t[0]===S.productType),map=S.offerTaxonomy||{},filters=S.productFilters||{},attrs=S.offerAttributes||{};let matched=allOffers().filter(o=>{let m=map[o.id];if(!(m&&m.category===cat.slug&&(!sub||m.subcategory===sub.slug)&&(!type||m.productType===type[0])))return false;return Object.entries(filters).every(([k,v])=>{if(!v)return true;let av=(attrs[o.id]||{})[k];return Array.isArray(av)?av.map(String).includes(String(v)):String(av??'').toLowerCase()===String(v).toLowerCase()})});let results=matched.length?`<div class="offers">${matched.map(offerCard).join('')}</div>`:'<div class="empty">No products or offers in this selection yet.</div>';let body=`<h1 class="title">${txName(cat)}</h1><p class="sub">Choose a subcategory, then a product type.</p><div class="chips">${txVisibleSubs(cat).map(s=>`<button class="chip ${S.subcategory===s.slug?'on':''}" onclick="chooseSub('${s.slug}')">${txName(s)}</button>`).join('')}</div>${sub?`<div class="section"><h3>${txName(sub)}</h3></div><div class="chips">${txVisibleTypes(cat,sub).map(t=>`<button class="chip ${S.productType===t[0]?'on':''}" onclick="chooseType('${t[0]}')">${txTypeName(t)}</button>`).join('')}</div>${type?categoryFilterFields(type):''}<div class="section"><h3>Products & Offers</h3></div>${results}`:''}`;return page(txName(cat),body,'home','home')}
function offerTaxonomyFields(){let cats=txAll();return `<label>Category</label><select id="offerCategory" class="field" onchange="updateOfferSubcategories()"><option value="">Select category</option>${cats.map(c=>`<option value="${c.slug}">${txName(c)}</option>`).join('')}</select><label>Subcategory</label><select id="offerSubcategory" class="field" onchange="updateOfferProductTypes()" disabled><option value="">Select subcategory</option></select><label>Product Type</label><select id="offerProductType" class="field" onchange="offerAttributeFields()" disabled><option value="">Select product type</option></select><div id="offerAttributes"></div>`}
function updateOfferSubcategories(){let cs=document.getElementById('offerCategory'),ss=document.getElementById('offerSubcategory'),ts=document.getElementById('offerProductType');let cat=txCat(cs.value);ss.innerHTML='<option value="">Select subcategory</option>'+(cat?txVisibleSubs(cat).map(s=>`<option value="${s.slug}">${txName(s)}</option>`).join(''):'');ss.disabled=!cat;ts.innerHTML='<option value="">Select product type</option>';ts.disabled=true;let box=document.getElementById('offerAttributes');if(box)box.innerHTML=''}
function updateOfferProductTypes(){let cat=txCat(document.getElementById('offerCategory').value),ss=document.getElementById('offerSubcategory'),ts=document.getElementById('offerProductType'),sub=txSub(cat,ss.value);ts.innerHTML='<option value="">Select product type</option>'+(sub?txVisibleTypes(cat,sub).map(t=>`<option value="${t[0]}">${txTypeName(t)}</option>`).join(''):'');ts.disabled=!sub;offerAttributeFields()}
function offerAttributeFields(){let cat=txCat(document.getElementById('offerCategory')?.value),sub=txSub(cat,document.getElementById('offerSubcategory')?.value),t=sub&&sub.types.find(x=>x[0]===document.getElementById('offerProductType')?.value),box=document.getElementById('offerAttributes');if(!box)return;let attrs=(t&&t[3])||[];box.innerHTML=attrs.map(a=>{let label=a.label||a.key,opts=a.options||[];if(a.input_type==='select')return `<label>${label}</label><select class="field" data-attr="${a.key}"><option value="">Select ${label}</option>${opts.map(o=>`<option>${o}</option>`).join('')}</select>`;if(a.input_type==='multiselect')return `<label>${label}</label><select class="field" data-attr="${a.key}" multiple>${opts.map(o=>`<option>${o}</option>`).join('')}</select>`;if(a.input_type==='boolean')return `<label class="switch"><b>${label}</b><input data-attr="${a.key}" type="checkbox"></label>`;return `<label>${label}</label><input class="field" data-attr="${a.key}" type="${a.input_type==='number'?'number':'text'}" placeholder="${label}">`}).join('')}
createOffer=function(){return page('Create Offer',`<div class="card"><input id="ot" class="field" placeholder="Offer title">${offerTaxonomyFields()}<input id="offerOriginalPrice" class="field" inputmode="decimal" placeholder="Original price"><input id="offerSalePrice" class="field" inputmode="decimal" placeholder="Offer price"><textarea id="offerDesc" class="field textarea" placeholder="Offer description"></textarea><select id="offerKind" class="field"><option>Standard Offer</option><option>Flash Sale</option><option>Featured Offer</option></select><select id="offerBranch" class="field"><option>All branches</option><option>Mansour</option><option>Karrada</option></select><input id="offerStart" class="field" type="datetime-local"><input id="offerEnd" class="field" type="datetime-local"><button class="secondary" onclick="previewOffer()">Preview Offer</button><button class="primary" onclick="publishOffer()">Publish Offer</button></div>`,'merchant')}
function collectOfferAttributes(){let out={};document.querySelectorAll('#offerAttributes [data-attr]').forEach(el=>{if(el.type==='checkbox')out[el.dataset.attr]=el.checked;else if(el.multiple)out[el.dataset.attr]=Array.from(el.selectedOptions).map(x=>x.value);else if(el.value!=='')out[el.dataset.attr]=el.value});return out}
function previewOffer(){let title=document.getElementById('ot')?.value.trim()||'Untitled Offer',price=document.getElementById('offerSalePrice')?.value.trim()||'—',cat=txCat(document.getElementById('offerCategory')?.value),sub=txSub(cat,document.getElementById('offerSubcategory')?.value);alert(title+'\n'+(cat?txName(cat):'No category')+(sub?' → '+txName(sub):'')+'\nOffer price: '+price)}
publishOffer=async function(){let title=document.getElementById('ot')?.value.trim(),catEl=document.getElementById('offerCategory'),subEl=document.getElementById('offerSubcategory'),typeEl=document.getElementById('offerProductType'),oldRaw=document.getElementById('offerOriginalPrice')?.value.trim(),saleRaw=document.getElementById('offerSalePrice')?.value.trim();if(!title)return alert('Enter an offer title.');if(!catEl?.value||!subEl?.value||!typeEl?.value)return alert('Select category, subcategory and product type.');let oldPrice=Number(oldRaw),salePrice=Number(saleRaw);if(!salePrice||salePrice<=0)return alert('Enter a valid offer price.');if(oldRaw&&(!oldPrice||oldPrice<salePrice))return alert('Original price must be equal to or higher than offer price.');let cur=D.markets[S.market]?.currency||'IQD',off=oldPrice>salePrice?Math.round((1-salePrice/oldPrice)*100)+'%':'0%',attrs=collectOfferAttributes(),desc=document.getElementById('offerDesc')?.value.trim()||'Merchant offer.',kind=(document.getElementById('offerKind')?.value||'Standard Offer').toLowerCase().includes('flash')?'flash':(document.getElementById('offerKind')?.value||'').toLowerCase().includes('featured')?'featured':'standard',branch=document.getElementById('offerBranch')?.value||null,start=document.getElementById('offerStart')?.value,end=document.getElementById('offerEnd')?.value,id=String(Date.now()),remoteMerchantId=null,remoteOfferId=null;if(window.MIRA_DB?.enabled){if(!S.isAuthenticated){S.afterAuth='createOffer';save();alert('Sign in to publish a merchant offer.');return go('auth')}try{let mp=await MIRA_DB.ensureMerchantProfile({business_name:S.merchant.name,phone:S.profile.phone,email:S.profile.email,country:S.market,city:S.city});let rr=await MIRA_DB.createOffer({title,description:desc,original_price:oldPrice||null,offer_price:salePrice,currency:cur,offer_type:kind,branch_scope:branch,attributes:attrs,category:catEl.value,subcategory:subEl.value,productType:typeEl.value,starts_at:start?new Date(start).toISOString():null,ends_at:end?new Date(end).toISOString():null});id=String(rr.id);remoteMerchantId=mp.id;remoteOfferId=rr.id}catch(e){return alert(e.message||'Could not publish the offer.')}}let offer={id,remoteOfferId,remoteMerchantId,shop:S.merchant.name,title,emoji:'🛍️',price:salePrice.toLocaleString()+' '+cur,old:oldPrice?oldPrice.toLocaleString():'',off,city:S.city,cat:catEl.value,desc};S.customOffers=S.customOffers||[];S.customOffers=S.customOffers.filter(x=>String(x.id)!==String(id));S.customOffers.push(offer);S.offerTaxonomy=S.offerTaxonomy||{};S.offerTaxonomy[id]={category:catEl.value,subcategory:subEl.value,productType:typeEl.value};S.offerAttributes=S.offerAttributes||{};S.offerAttributes[id]=attrs;S.merchant.offers=(S.merchant.offers||0)+1;save();alert('Offer published.');go('merchant')}
async function syncRemoteOffers(){if(!window.MIRA_DB?.enabled)return;try{let rows=await MIRA_DB.listPublicOffers(),changed=false;S.customOffers=S.customOffers||[];S.offerTaxonomy=S.offerTaxonomy||{};S.offerAttributes=S.offerAttributes||{};for(const r of rows){let id=String(r.id);if(S.customOffers.some(x=>String(x.id)===id))continue;let old=Number(r.original_price||0),sale=Number(r.offer_price||0),off=old>sale?Math.round((1-sale/old)*100)+'%':'0%',tax=r.attributes?._taxonomy||{},attrs=Object.assign({},r.attributes||{});delete attrs._taxonomy;let merchant=Array.isArray(r.merchant_profiles)?r.merchant_profiles[0]:r.merchant_profiles||{};S.customOffers.push({id,remoteOfferId:r.id,remoteMerchantId:r.merchant_id,shop:merchant.business_name||'MIRA Merchant',title:r.title,emoji:'🛍️',price:sale.toLocaleString()+' '+(r.currency||'IQD'),old:old?old.toLocaleString():'',off,city:merchant.city||'',cat:tax.category||'',desc:r.description||'Merchant offer.'});S.offerTaxonomy[id]={category:tax.category||'',subcategory:tax.subcategory||'',productType:tax.productType||''};S.offerAttributes[id]=attrs;changed=true}if(changed){save();render()}}catch(e){console.warn('MIRA remote offers sync failed',e)}}
function taxonomyAdmin(){let cats=txSource(),ov=S.taxonomyOverrides||{};return page('Product Taxonomy',`<div class="notice">Category → Subcategory → Product Type → Attributes</div><button class="primary" onclick="addTaxonomyCategory()">+ Add Category</button>${cats.map(c=>`<div class="card" style="margin-bottom:10px"><div class="item"><div class="grow"><b>${txName(c)}</b><div class="small">${c.subs.length} subcategories</div></div><button class="link" onclick="editTaxCategory('${c.slug}')">Edit</button><button class="link" onclick="toggleTaxCategory('${c.slug}')">${(ov.hidden||[]).includes(c.slug)?'Show':'Hide'}</button><button class="link" onclick="moveTaxCategory('${c.slug}',-1)">↑</button><button class="link" onclick="moveTaxCategory('${c.slug}',1)">↓</button></div><button class="secondary" onclick="addTaxSubcategory('${c.slug}')">+ Subcategory</button>${c.subs.map(s=>{let sk=txSubKey(c,s);return `<div class="item"><div class="grow"><b>${txName(s)}</b><div class="small">${s.types.length} product types</div></div><button class="link" onclick="editTaxSubcategory('${c.slug}','${s.slug}')">Edit</button><button class="link" onclick="toggleTaxSubcategory('${c.slug}','${s.slug}')">${(ov.hiddenSubs||[]).includes(sk)?'Show':'Hide'}</button><button class="link" onclick="moveTaxSubcategory('${c.slug}','${s.slug}',-1)">↑</button><button class="link" onclick="moveTaxSubcategory('${c.slug}','${s.slug}',1)">↓</button><button class="link" onclick="deleteTaxSubcategory('${c.slug}','${s.slug}')">×</button></div><button class="secondary" onclick="addTaxProductType('${c.slug}','${s.slug}')">+ Product Type</button>${s.types.map(t=>{let tk=txTypeKey(c,s,t);return `<div class="item"><div class="grow"><span>${txTypeName(t)}</span><div class="small">${((t[3]||[]).map(a=>a.label||a.key).join(' • '))||'No attributes'}</div></div><button class="link" onclick="addTaxAttribute('${c.slug}','${s.slug}','${t[0]}')">+ Attr</button><button class="link" onclick="editTaxProductType('${c.slug}','${s.slug}','${t[0]}')">Edit</button><button class="link" onclick="toggleTaxProductType('${c.slug}','${s.slug}','${t[0]}')">${(ov.hiddenTypes||[]).includes(tk)?'Show':'Hide'}</button><button class="link" onclick="moveTaxProductType('${c.slug}','${s.slug}','${t[0]}',-1)">↑</button><button class="link" onclick="moveTaxProductType('${c.slug}','${s.slug}','${t[0]}',1)">↓</button><button class="link" onclick="deleteTaxProductType('${c.slug}','${s.slug}','${t[0]}')">×</button></div>${(t[3]||[]).map(a=>`<div class="item"><div class="grow"><span>${a.label||a.key}</span><div class="small">${a.input_type||'text'}${(a.options||[]).length?' • '+a.options.join(', '):''}</div></div><button class="link" onclick="editTaxAttribute('${c.slug}','${s.slug}','${t[0]}','${a.key}')">Edit</button><button class="link" onclick="deleteTaxAttribute('${c.slug}','${s.slug}','${t[0]}','${a.key}')">×</button></div>`).join('')}`}).join('')}`}).join('')}</div>`).join('')}`,'admin')}
const _admin=admin;admin=function(){let h=_admin();return h.replace('<div class="section"><h3>Admin Tools</h3></div>','<div class="section"><h3>Admin Tools</h3></div><div class="item" onclick="go(\'taxonomyAdmin\')"><div class="ico">☷</div><div class="grow"><b>Product Taxonomy</b></div>›</div><div class="item" onclick="go(\'productClassification\')"><div class="ico">↹</div><div class="grow"><b>Product Classification</b></div>›</div>')}
function productClassificationAdmin(){let map=S.offerTaxonomy||{};return page('Product Classification',allOffers().map(o=>{let m=map[o.id]||{},cat=txCat(m.category),sub=txSub(cat,m.subcategory),type=sub&&sub.types.find(t=>t[0]===m.productType);return `<div class="item"><div class="ico">${o.emoji}</div><div class="grow"><b>${o.title}</b><div class="small">${cat?txName(cat):'Unclassified'}${sub?' → '+txName(sub):''}${type?' → '+txTypeName(type):''}</div></div><button class="link" onclick="editOfferTaxonomy('${jsId(o.id)}')">Edit</button></div>`}).join(''),'admin')}
function editOfferTaxonomy(id){S.adminOffer=id;save();go('productClassificationEdit')}
function productClassificationEditor(){let o=findOffer(S.adminOffer)||allOffers()[0],m=(S.offerTaxonomy||{})[o.id]||{},cats=txSource(),cat=txCat(m.category)||cats[0],sub=txSub(cat,m.subcategory)||cat?.subs?.[0],type=sub&&sub.types.find(t=>t[0]===m.productType)||sub?.types?.[0];return page('Edit Product Category',`<div class="card"><b>${o.title}</b><div class="small">${o.shop}</div><label>Category</label><select id="adminOfferCategory" class="field" onchange="updateAdminOfferSubs()">${cats.map(c=>`<option value="${c.slug}" ${cat&&c.slug===cat.slug?'selected':''}>${txName(c)}</option>`).join('')}</select><label>Subcategory</label><select id="adminOfferSubcategory" class="field" onchange="updateAdminOfferTypes()">${(cat?.subs||[]).map(s=>`<option value="${s.slug}" ${sub&&s.slug===sub.slug?'selected':''}>${txName(s)}</option>`).join('')}</select><label>Product Type</label><select id="adminOfferProductType" class="field">${(sub?.types||[]).map(t=>`<option value="${t[0]}" ${type&&t[0]===type[0]?'selected':''}>${txTypeName(t)}</option>`).join('')}</select><button class="primary" onclick="saveAdminOfferTaxonomy()">Save Classification</button></div>`,'productClassification')}
function updateAdminOfferSubs(){let cat=txCat(document.getElementById('adminOfferCategory').value),s=document.getElementById('adminOfferSubcategory'),t=document.getElementById('adminOfferProductType');s.innerHTML=(cat?.subs||[]).map(x=>`<option value="${x.slug}">${txName(x)}</option>`).join('');let sub=cat?.subs?.[0];t.innerHTML=(sub?.types||[]).map(x=>`<option value="${x[0]}">${txTypeName(x)}</option>`).join('')}
function updateAdminOfferTypes(){let cat=txCat(document.getElementById('adminOfferCategory').value),sub=txSub(cat,document.getElementById('adminOfferSubcategory').value),t=document.getElementById('adminOfferProductType');t.innerHTML=(sub?.types||[]).map(x=>`<option value="${x[0]}">${txTypeName(x)}</option>`).join('')}
function saveAdminOfferTaxonomy(){let id=S.adminOffer,c=document.getElementById('adminOfferCategory').value,s=document.getElementById('adminOfferSubcategory').value,t=document.getElementById('adminOfferProductType').value;if(!c||!s||!t)return alert('Select category, subcategory and product type.');S.offerTaxonomy=S.offerTaxonomy||{};S.offerTaxonomy[id]={category:c,subcategory:s,productType:t};save();alert('Classification updated.');go('productClassification')}
function taxSlug(v){return v.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-')}
function ensureTaxOverrides(){S.taxonomyOverrides=Object.assign({hidden:[],order:[],hiddenSubs:[],hiddenTypes:[],subOrder:{},typeOrder:{}},S.taxonomyOverrides||{});return S.taxonomyOverrides}
function toggleTaxCategory(slug){let ov=ensureTaxOverrides(),h=ov.hidden;ov.hidden=h.includes(slug)?h.filter(x=>x!==slug):[...h,slug];save();render()}
function moveTaxCategory(slug,d){let ov=ensureTaxOverrides(),all=txSource().map(x=>x.slug),o=ov.order.length?ov.order.filter(x=>all.includes(x)):[...all],i=o.indexOf(slug),j=Math.max(0,Math.min(o.length-1,i+d));if(i<0||i===j)return;[o[i],o[j]]=[o[j],o[i]];ov.order=o;save();render()}
function addTaxonomyCategory(){let en=prompt('Category name (English)');if(!en)return;let ar=prompt('اسم القسم بالعربي')||en,slug=taxSlug(en);if(txCat(slug))return alert('Category already exists.');let data=JSON.parse(JSON.stringify(txSource()));data.push({slug,ar,en,subs:[]});S.taxonomyData=data;save();render()}
function editTaxCategory(slug){let cat=txCat(slug);if(!cat)return;let en=prompt('Category name (English)',cat.en);if(!en)return;let ar=prompt('اسم القسم بالعربي',cat.ar)||en;cat.en=en;cat.ar=ar;persistTaxonomy();render()}
function addTaxSubcategory(catSlug){let cat=txCat(catSlug),en=prompt('Subcategory name (English)');if(!cat||!en)return;let ar=prompt('اسم القسم الفرعي بالعربي')||en,slug=taxSlug(en);if(cat.subs.some(x=>x.slug===slug))return alert('Subcategory already exists.');cat.subs.push({slug,ar,en,types:[]});persistTaxonomy();render()}
function editTaxSubcategory(catSlug,subSlug){let sub=txSub(txCat(catSlug),subSlug);if(!sub)return;let en=prompt('Subcategory name (English)',sub.en);if(!en)return;let ar=prompt('اسم القسم الفرعي بالعربي',sub.ar)||en;sub.en=en;sub.ar=ar;persistTaxonomy();render()}
function toggleTaxSubcategory(catSlug,subSlug){let cat=txCat(catSlug),sub=txSub(cat,subSlug);if(!sub)return;let ov=ensureTaxOverrides(),k=txSubKey(cat,sub),h=ov.hiddenSubs;ov.hiddenSubs=h.includes(k)?h.filter(x=>x!==k):[...h,k];save();render()}
function moveTaxSubcategory(catSlug,subSlug,d){let cat=txCat(catSlug);if(!cat)return;let ov=ensureTaxOverrides(),all=cat.subs.map(x=>x.slug),o=(ov.subOrder[catSlug]||[]).filter(x=>all.includes(x));if(!o.length)o=[...all];let i=o.indexOf(subSlug),j=Math.max(0,Math.min(o.length-1,i+d));if(i<0||i===j)return;[o[i],o[j]]=[o[j],o[i]];ov.subOrder[catSlug]=o;save();render()}
function deleteTaxSubcategory(catSlug,subSlug){let cat=txCat(catSlug);if(!cat)return;if(confirm('Delete this subcategory and its product types?')){cat.subs=cat.subs.filter(x=>x.slug!==subSlug);persistTaxonomy();render()}}
function addTaxProductType(catSlug,subSlug){let sub=txSub(txCat(catSlug),subSlug),en=prompt('Product type (English)');if(!sub||!en)return;let ar=prompt('نوع المنتج بالعربي')||en,slug=taxSlug(en);if(sub.types.some(x=>x[0]===slug))return alert('Product type already exists.');sub.types.push([slug,ar,en,[]]);persistTaxonomy();render()}
function editTaxProductType(catSlug,subSlug,typeSlug){let sub=txSub(txCat(catSlug),subSlug),t=sub&&sub.types.find(x=>x[0]===typeSlug);if(!t)return;let en=prompt('Product type (English)',t[2]);if(!en)return;let ar=prompt('نوع المنتج بالعربي',t[1])||en;t[1]=ar;t[2]=en;persistTaxonomy();render()}
function deleteTaxProductType(catSlug,subSlug,typeSlug){let sub=txSub(txCat(catSlug),subSlug);if(!sub)return;if(confirm('Delete this product type?')){sub.types=sub.types.filter(x=>x[0]!==typeSlug);persistTaxonomy();render()}}
function toggleTaxProductType(catSlug,subSlug,typeSlug){let cat=txCat(catSlug),sub=txSub(cat,subSlug),t=sub&&sub.types.find(x=>x[0]===typeSlug);if(!t)return;let ov=ensureTaxOverrides(),k=txTypeKey(cat,sub,t),h=ov.hiddenTypes;ov.hiddenTypes=h.includes(k)?h.filter(x=>x!==k):[...h,k];save();render()}
function moveTaxProductType(catSlug,subSlug,typeSlug,d){let sub=txSub(txCat(catSlug),subSlug);if(!sub)return;let ov=ensureTaxOverrides(),key=catSlug+'/'+subSlug,all=sub.types.map(x=>x[0]),o=(ov.typeOrder[key]||[]).filter(x=>all.includes(x));if(!o.length)o=[...all];let i=o.indexOf(typeSlug),j=Math.max(0,Math.min(o.length-1,i+d));if(i<0||i===j)return;[o[i],o[j]]=[o[j],o[i]];ov.typeOrder[key]=o;save();render()}
function addTaxAttribute(catSlug,subSlug,typeSlug){let sub=txSub(txCat(catSlug),subSlug),t=sub&&sub.types.find(x=>x[0]===typeSlug);if(!t)return;let label=prompt('Attribute name, e.g. Size, Color, Volume');if(!label)return;let key=taxSlug(label),kind=prompt('Input type: text, number, select, multiselect, boolean','select')||'select';if(!['text','number','select','multiselect','boolean'].includes(kind))return alert('Invalid input type.');let opts=[];if(kind==='select'||kind==='multiselect'){let raw=prompt('Options separated by commas, e.g. S,M,L,XL','');opts=(raw||'').split(',').map(x=>x.trim()).filter(Boolean)}t[3]=t[3]||[];t[3].push({key,label,input_type:kind,options:opts,is_filterable:true});persistTaxonomy();render()}
function editTaxAttribute(catSlug,subSlug,typeSlug,key){let sub=txSub(txCat(catSlug),subSlug),t=sub&&sub.types.find(x=>x[0]===typeSlug),a=t&&((t[3]||[]).find(x=>x.key===key));if(!a)return;let label=prompt('Attribute name',a.label||a.key);if(!label)return;let kind=prompt('Input type: text, number, select, multiselect, boolean',a.input_type||'text')||a.input_type;if(!['text','number','select','multiselect','boolean'].includes(kind))return alert('Invalid input type.');a.label=label;a.input_type=kind;if(kind==='select'||kind==='multiselect'){let raw=prompt('Options separated by commas',(a.options||[]).join(','));a.options=(raw||'').split(',').map(x=>x.trim()).filter(Boolean)}else a.options=[];persistTaxonomy();render()}
function deleteTaxAttribute(catSlug,subSlug,typeSlug,key){let sub=txSub(txCat(catSlug),subSlug),t=sub&&sub.types.find(x=>x[0]===typeSlug);if(!t)return;if(confirm('Delete this attribute?')){t[3]=(t[3]||[]).filter(x=>x.key!==key);persistTaxonomy();render()}}
